"""Exception hierarchy for microdb."""

from __future__ import annotations


class MicroDBError(Exception):
    """Base class for all microdb errors."""


class LexError(MicroDBError):
    """Raised when the lexer encounters an invalid character or token."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset: int = offset


class ParseError(MicroDBError):
    """Raised when the parser encounters invalid syntax."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset: int = offset


class SchemaError(MicroDBError):
    """Raised when a table definition or its rows are invalid."""


class TypeMismatchError(MicroDBError):
    """Raised when an operation receives a value of an incompatible type."""


class UnknownColumnError(MicroDBError):
    """Raised when a column reference cannot be resolved."""


class AmbiguousColumnError(MicroDBError):
    """Raised when an unqualified column name matches more than one table."""


class UnknownTableError(MicroDBError):
    """Raised when a qualified reference names an unknown table."""


class UnknownFunctionError(MicroDBError):
    """Raised when a scalar function name is not recognized."""


class ArityError(MicroDBError):
    """Raised when a function is called with the wrong number of arguments."""


class AggregateError(MicroDBError):
    """Raised when an aggregate function is used illegally."""


class GroupingError(MicroDBError):
    """Raised when a SELECT item violates GROUP BY rules."""

"""Value model: five kinds (INT, FLOAT, TEXT, BOOL, NULL), three-valued logic,
comparison and arithmetic with SQL NULL semantics.

Note: ``bool`` is a subclass of ``int`` in Python, so every numeric check in this
module excludes ``bool`` explicitly.
"""

from __future__ import annotations

from .errors import TypeMismatchError

INT = "INT"
FLOAT = "FLOAT"
TEXT = "TEXT"
BOOL = "BOOL"
NULL = "NULL"


def type_of(v: object) -> str:
    """Return the kind name of a value: INT, FLOAT, TEXT, BOOL or NULL."""
    if v is None:
        return NULL
    if isinstance(v, bool):
        return BOOL
    if isinstance(v, int):
        return INT
    if isinstance(v, float):
        return FLOAT
    if isinstance(v, str):
        return TEXT
    raise TypeMismatchError(f"unsupported value: {v!r}")


def is_numeric(v: object) -> bool:
    """True for INT and FLOAT values; False for BOOL, TEXT and NULL."""
    return isinstance(v, (int, float)) and not isinstance(v, bool)


# ---------------------------------------------------------------------------
# Three-valued logic.  A logical value is True, False or None (UNKNOWN).
# ---------------------------------------------------------------------------

def and_(a: bool | None, b: bool | None) -> bool | None:
    """Logical AND under three-valued logic."""
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or_(a: bool | None, b: bool | None) -> bool | None:
    """Logical OR under three-valued logic."""
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not_(a: bool | None) -> bool | None:
    """Logical NOT under three-valued logic; NOT UNKNOWN is UNKNOWN."""
    if a is None:
        return None
    return not a


# ---------------------------------------------------------------------------
# Comparison
# ---------------------------------------------------------------------------

def _cmp_operands(a: object, b: object) -> tuple[object, object]:
    """Validate a pair of non-NULL operands for comparison."""
    ta, tb = type_of(a), type_of(b)
    if is_numeric(a) and is_numeric(b):
        return a, b
    if ta == TEXT and tb == TEXT:
        return a, b
    if ta == BOOL and tb == BOOL:
        return a, b
    raise TypeMismatchError(f"cannot compare {ta} with {tb}")


def compare_eq(a: object, b: object) -> bool | None:
    """Equality comparison; UNKNOWN (None) if either operand is NULL."""
    if a is None or b is None:
        return None
    x, y = _cmp_operands(a, b)
    return bool(x == y)


def compare_lt(a: object, b: object) -> bool | None:
    """Less-than comparison; UNKNOWN (None) if either operand is NULL."""
    if a is None or b is None:
        return None
    x, y = _cmp_operands(a, b)
    return bool(x < y)


# ---------------------------------------------------------------------------
# Arithmetic
# ---------------------------------------------------------------------------

def arith(op: str, a: object, b: object) -> object:
    """Apply an arithmetic operator ('+', '-', '*', '/', '%') with NULL
    propagation.  Division or modulo by zero yields NULL, not an error."""
    if a is None or b is None:
        return None
    if not is_numeric(a) or not is_numeric(b):
        raise TypeMismatchError(
            f"operator {op} requires numeric operands, "
            f"got {type_of(a)} and {type_of(b)}"
        )
    if op == "+":
        return a + b  # type: ignore[operator]
    if op == "-":
        return a - b  # type: ignore[operator]
    if op == "*":
        return a * b  # type: ignore[operator]
    if op == "/":
        if b == 0:
            return None
        return a / b  # type: ignore[operator]  # always FLOAT
    if op == "%":
        if type_of(a) != INT or type_of(b) != INT:
            raise TypeMismatchError("operator % requires INT operands")
        if b == 0:
            return None
        return a % b  # type: ignore[operator]
    raise TypeMismatchError(f"unknown arithmetic operator {op!r}")


def negate(a: object) -> object:
    """Unary minus; requires a numeric operand and preserves its type."""
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError(f"cannot negate {type_of(a)}")
    return -a  # type: ignore[operator]

"""Schema layer: Column and Table."""

from __future__ import annotations

import dataclasses

from .errors import SchemaError
from .value import BOOL, FLOAT, INT, TEXT

_VALID_TYPES = (INT, FLOAT, TEXT, BOOL)


@dataclasses.dataclass(frozen=True)
class Column:
    name: str
    type: str  # "INT" | "FLOAT" | "TEXT" | "BOOL"


def _check_cell(col: Column, value: object) -> object:
    """Validate one cell against its column type; returns the stored value."""
    if value is None:
        return None
    if col.type == BOOL:
        if isinstance(value, bool):
            return value
        raise SchemaError(f"column {col.name!r}: expected BOOL, got {value!r}")
    if col.type == INT:
        # bool is a subclass of int; an INT column rejects True/False.
        if isinstance(value, int) and not isinstance(value, bool):
            return value
        raise SchemaError(f"column {col.name!r}: expected INT, got {value!r}")
    if col.type == FLOAT:
        # FLOAT widening: an int is accepted and stored converted to float.
        if isinstance(value, float):
            return value
        if isinstance(value, int) and not isinstance(value, bool):
            return float(value)
        raise SchemaError(f"column {col.name!r}: expected FLOAT, got {value!r}")
    if col.type == TEXT:
        if isinstance(value, str):
            return value
        raise SchemaError(f"column {col.name!r}: expected TEXT, got {value!r}")
    raise SchemaError(f"column {col.name!r}: unknown type {col.type!r}")


class Table:
    """A named table with typed columns and validated rows."""

    def __init__(
        self,
        name: str,
        columns: list[Column],
        rows: list[list[object]],
    ) -> None:
        if not columns:
            raise SchemaError("table must have at least one column")
        seen: set[str] = set()
        for col in columns:
            if col.type not in _VALID_TYPES:
                raise SchemaError(f"invalid column type {col.type!r}")
            if col.name in seen:
                raise SchemaError(f"duplicate column name {col.name!r}")
            seen.add(col.name)
        stored: list[list[object]] = []
        for row in rows:
            if len(row) != len(columns):
                raise SchemaError(
                    f"row has {len(row)} cells, expected {len(columns)}"
                )
            stored.append(
                [_check_cell(col, v) for col, v in zip(columns, row)]
            )
        self._name = name
        self._columns = list(columns)
        self._rows = stored
        self._index = {col.name: i for i, col in enumerate(columns)}

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return list(self._columns)

    @property
    def rows(self) -> list[list[object]]:
        return list(self._rows)

    def column_index(self, name: str) -> int:
        """Return the zero-based index of a column; SchemaError if unknown."""
        try:
            return self._index[name]
        except KeyError:
            raise SchemaError(f"unknown column {name!r} in table {self._name!r}")

