"""Lexer for the microdb query language."""

from __future__ import annotations

import dataclasses

from .errors import LexError

KEYWORDS = frozenset(
    "SELECT DISTINCT FROM INNER LEFT JOIN ON WHERE GROUP BY HAVING ORDER "
    "ASC DESC LIMIT OFFSET AS AND OR NOT IS NULL TRUE FALSE".split()
)

_OPS2 = ("<>", "<=", ">=")
_OPS1 = set("=<>+-*/%(),.")


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str  # "INT" | "FLOAT" | "TEXT" | "IDENT" | "KW" | "OP" | "EOF"
    value: object  # literal value, uppercased keyword, identifier, or operator
    offset: int  # zero-based character offset of the token start
    text: str  # raw source slice

    @property
    def end(self) -> int:
        """Offset just past the token."""
        return self.offset + len(self.text)


def tokenize(text: str) -> list[Token]:
    """Split query text into tokens; raises LexError on invalid input."""
    tokens: list[Token] = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch in " \t\r\n":
            i += 1
        elif ch == "-" and text.startswith("--", i):
            nl = text.find("\n", i)
            i = n if nl == -1 else nl + 1
        elif ch == "'":
            tok, i = _lex_text(text, i)
            tokens.append(tok)
        elif ch.isdigit() or (ch == "." and i + 1 < n and text[i + 1].isdigit()):
            tok, i = _lex_number(text, i)
            tokens.append(tok)
        elif ch.isalpha() or ch == "_":
            tok, i = _lex_word(text, i)
            tokens.append(tok)
        else:
            tok, i = _lex_operator(text, i)
            tokens.append(tok)
    tokens.append(Token("EOF", None, n, ""))
    return tokens


def _lex_text(text: str, i: int) -> tuple[Token, int]:
    """Lex a single-quoted text literal; '' is an escaped quote."""
    start = i
    i += 1
    chars: list[str] = []
    n = len(text)
    while i < n:
        ch = text[i]
        if ch == "'":
            if i + 1 < n and text[i + 1] == "'":
                chars.append("'")
                i += 2
            else:
                i += 1
                return Token("TEXT", "".join(chars), start, text[start:i]), i
        else:
            chars.append(ch)
            i += 1
    raise LexError("unterminated text literal", start)


def _lex_number(text: str, i: int) -> tuple[Token, int]:
    """Lex an integer or float literal (floats may carry an exponent)."""
    start = i
    n = len(text)
    is_float = False
    while i < n and text[i].isdigit():
        i += 1
    if i < n and text[i] == ".":
        is_float = True
        i += 1
        while i < n and text[i].isdigit():
            i += 1
    if i < n and text[i] in "eE":
        j = i + 1
        if j < n and text[j] in "+-":
            j += 1
        if j < n and text[j].isdigit():
            is_float = True
            i = j
            while i < n and text[i].isdigit():
                i += 1
    raw = text[start:i]
    if is_float:
        return Token("FLOAT", float(raw), start, raw), i
    return Token("INT", int(raw), start, raw), i


def _lex_word(text: str, i: int) -> tuple[Token, int]:
    """Lex an identifier or keyword (keywords match case insensitively)."""
    start = i
    n = len(text)
    while i < n and (text[i].isalnum() or text[i] == "_"):
        i += 1
    raw = text[start:i]
    upper = raw.upper()
    if upper in KEYWORDS:
        return Token("KW", upper, start, raw), i
    return Token("IDENT", raw, start, raw), i


def _lex_operator(text: str, i: int) -> tuple[Token, int]:
    """Lex an operator or punctuation token."""
    two = text[i : i + 2]
    if two in _OPS2:
        return Token("OP", two, i, two), i + 2
    ch = text[i]
    if ch in _OPS1:
        return Token("OP", ch, i, ch), i + 1
    raise LexError(f"unexpected character {ch!r}", i)

"""Parser: tokenize + recursive-descent parse producing a Query AST.

Every AST node carries ``start``/``end`` offsets into the source text so the
executor can recover the (whitespace-collapsed) source text of an expression
for output column naming.  Offsets never take part in node equality.
"""

from __future__ import annotations

import dataclasses

from .aggregate import AGGREGATE_NAMES, contains_aggregate
from .errors import ParseError
from .lexer import Token, tokenize


# ---------------------------------------------------------------------------
# AST nodes (keyword-only fields; offsets excluded from equality)
# ---------------------------------------------------------------------------

@dataclasses.dataclass(frozen=True, kw_only=True)
class Node:
    start: int = dataclasses.field(default=0, compare=False)
    end: int = dataclasses.field(default=0, compare=False)


@dataclasses.dataclass(frozen=True, kw_only=True)
class Literal(Node):
    value: object = None


@dataclasses.dataclass(frozen=True, kw_only=True)
class ColumnRef(Node):
    name: str = ""
    table: str | None = None


@dataclasses.dataclass(frozen=True, kw_only=True)
class Star(Node):
    table: str | None = None


@dataclasses.dataclass(frozen=True, kw_only=True)
class FuncCall(Node):
    name: str = ""
    args: tuple[Node, ...] = ()
    star: bool = False  # count(*)


@dataclasses.dataclass(frozen=True, kw_only=True)
class UnaryOp(Node):
    op: str = "-"
    operand: Node = dataclasses.field(default_factory=Node)


@dataclasses.dataclass(frozen=True, kw_only=True)
class BinaryOp(Node):
    op: str = ""
    left: Node = dataclasses.field(default_factory=Node)
    right: Node = dataclasses.field(default_factory=Node)


@dataclasses.dataclass(frozen=True, kw_only=True)
class NotOp(Node):
    operand: Node = dataclasses.field(default_factory=Node)


@dataclasses.dataclass(frozen=True, kw_only=True)
class IsNull(Node):
    operand: Node = dataclasses.field(default_factory=Node)
    negated: bool = False


@dataclasses.dataclass(frozen=True)
class SelectItem:
    expr: Node  # Star or an expression
    alias: str | None


@dataclasses.dataclass(frozen=True)
class OrderItem:
    expr: Node
    desc: bool


@dataclasses.dataclass(frozen=True)
class Join:
    kind: str  # "INNER" | "LEFT"
    table: str
    on: Node


@dataclasses.dataclass(frozen=True)
class Query:
    distinct: bool
    select: tuple[SelectItem, ...]
    from_table: str
    join: Join | None
    where: Node | None
    group_by: tuple[Node, ...]
    having: Node | None
    order_by: tuple[OrderItem, ...]
    limit: int | None
    offset: int | None
    source: str


def parse(text: str) -> Query:
    """Parse query text into a Query; raises LexError or ParseError."""
    return _Parser(tokenize(text), text).parse_query()


# ---------------------------------------------------------------------------
# Recursive-descent parser
# ---------------------------------------------------------------------------

class _Parser:
    def __init__(self, tokens: list[Token], source: str) -> None:
        self.tokens = tokens
        self.source = source
        self.pos = 0

    # -- token helpers ------------------------------------------------------

    def peek(self, ahead: int = 0) -> Token:
        return self.tokens[min(self.pos + ahead, len(self.tokens) - 1)]

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        if tok.kind != "EOF":
            self.pos += 1
        return tok

    def at_kw(self, kw: str) -> bool:
        t = self.peek()
        return t.kind == "KW" and t.value == kw

    def at_op(self, op: str) -> bool:
        t = self.peek()
        return t.kind == "OP" and t.value == op

    def accept_kw(self, kw: str) -> Token | None:
        if self.at_kw(kw):
            return self.advance()
        return None

    def accept_op(self, op: str) -> Token | None:
        if self.at_op(op):
            return self.advance()
        return None

    def expect_kw(self, kw: str) -> Token:
        tok = self.accept_kw(kw)
        if tok is None:
            raise ParseError(f"expected {kw}", self.peek().offset)
        return tok

    def expect_op(self, op: str) -> Token:
        tok = self.accept_op(op)
        if tok is None:
            raise ParseError(f"expected {op!r}", self.peek().offset)
        return tok

    def expect_ident(self) -> Token:
        tok = self.peek()
        if tok.kind != "IDENT":
            raise ParseError("expected an identifier", tok.offset)
        return self.advance()

    # -- query --------------------------------------------------------------

    def parse_query(self) -> Query:
        self.expect_kw("SELECT")
        distinct = self.accept_kw("DISTINCT") is not None
        select = self.parse_select_list()
        self.expect_kw("FROM")
        from_table = str(self.expect_ident().value)
        join = self.parse_join()
        where = self.parse_expr() if self.accept_kw("WHERE") else None
        group_by = self.parse_group_by()
        having = self.parse_expr() if self.accept_kw("HAVING") else None
        order_by = self.parse_order_by()
        limit = self.parse_int_clause("LIMIT")
        offset = self.parse_int_clause("OFFSET")
        end = self.peek()
        if end.kind != "EOF":
            raise ParseError(f"unexpected {end.text!r}", end.offset)
        return Query(
            distinct=distinct, select=select, from_table=from_table,
            join=join, where=where, group_by=group_by, having=having,
            order_by=order_by, limit=limit, offset=offset, source=self.source,
        )

    def parse_int_clause(self, kw: str) -> int | None:
        if self.accept_kw(kw) is None:
            return None
        tok = self.peek()
        if tok.kind != "INT":
            raise ParseError(f"{kw} requires an integer", tok.offset)
        self.advance()
        return int(tok.value)  # type: ignore[arg-type]

    def parse_select_list(self) -> tuple[SelectItem, ...]:
        items = [self.parse_select_item()]
        while self.accept_op(","):
            items.append(self.parse_select_item())
        return tuple(items)

    def parse_select_item(self) -> SelectItem:
        tok = self.peek()
        if self.accept_op("*"):
            expr: Node = Star(start=tok.offset, end=tok.end)
        elif (tok.kind == "IDENT" and self.peek(1).value == "."
              and self.peek(2).value == "*"):
            self.advance()
            self.advance()
            star = self.advance()
            expr = Star(table=str(tok.value), start=tok.offset, end=star.end)
        else:
            expr = self.parse_expr()
        alias = None
        if self.accept_kw("AS"):
            alias = str(self.expect_ident().value)
        return SelectItem(expr=expr, alias=alias)

    def parse_join(self) -> Join | None:
        kind: str | None = None
        if self.accept_kw("INNER"):
            kind = "INNER"
            self.expect_kw("JOIN")
        elif self.accept_kw("LEFT"):
            kind = "LEFT"
            self.expect_kw("JOIN")
        elif self.accept_kw("JOIN"):
            kind = "INNER"
        if kind is None:
            return None
        table = str(self.expect_ident().value)
        self.expect_kw("ON")
        return Join(kind=kind, table=table, on=self.parse_expr())

    def parse_group_by(self) -> tuple[Node, ...]:
        if self.accept_kw("GROUP") is None:
            return ()
        self.expect_kw("BY")
        exprs = [self.parse_expr()]
        while self.accept_op(","):
            exprs.append(self.parse_expr())
        return tuple(exprs)

    def parse_order_by(self) -> tuple[OrderItem, ...]:
        if self.accept_kw("ORDER") is None:
            return ()
        self.expect_kw("BY")
        items = [self.parse_order_item()]
        while self.accept_op(","):
            items.append(self.parse_order_item())
        return tuple(items)

    def parse_order_item(self) -> OrderItem:
        expr = self.parse_expr()
        desc = False
        if self.accept_kw("ASC"):
            desc = False
        elif self.accept_kw("DESC"):
            desc = True
        return OrderItem(expr=expr, desc=desc)

    # -- expressions --------------------------------------------------------

    def parse_expr(self) -> Node:
        return self.parse_or()

    def parse_or(self) -> Node:
        node = self.parse_and()
        while self.at_kw("OR"):
            self.advance()
            right = self.parse_and()
            node = BinaryOp(op="OR", left=node, right=right,
                            start=node.start, end=right.end)
        return node

    def parse_and(self) -> Node:
        node = self.parse_not()
        while self.at_kw("AND"):
            self.advance()
            right = self.parse_not()
            node = BinaryOp(op="AND", left=node, right=right,
                            start=node.start, end=right.end)
        return node

    def parse_not(self) -> Node:
        tok = self.accept_kw("NOT")
        if tok is not None:
            operand = self.parse_not()
            return NotOp(operand=operand, start=tok.offset, end=operand.end)
        return self.parse_predicate()

    def parse_predicate(self) -> Node:
        node = self.parse_additive()
        for op in ("=", "<>", "<=", ">=", "<", ">"):
            if self.at_op(op):
                self.advance()
                right = self.parse_additive()
                return BinaryOp(op=op, left=node, right=right,
                                start=node.start, end=right.end)
        if self.accept_kw("IS"):
            negated = self.accept_kw("NOT") is not None
            null_tok = self.expect_kw("NULL")
            return IsNull(operand=node, negated=negated,
                          start=node.start, end=null_tok.end)
        return node

    def parse_additive(self) -> Node:
        node = self.parse_multiplicative()
        while self.at_op("+") or self.at_op("-"):
            op = str(self.advance().value)
            right = self.parse_multiplicative()
            node = BinaryOp(op=op, left=node, right=right,
                            start=node.start, end=right.end)
        return node

    def parse_multiplicative(self) -> Node:
        node = self.parse_unary()
        while self.at_op("*") or self.at_op("/") or self.at_op("%"):
            op = str(self.advance().value)
            right = self.parse_unary()
            node = BinaryOp(op=op, left=node, right=right,
                            start=node.start, end=right.end)
        return node

    def parse_unary(self) -> Node:
        tok = self.accept_op("-")
        if tok is not None:
            operand = self.parse_unary()
            return UnaryOp(op="-", operand=operand,
                           start=tok.offset, end=operand.end)
        return self.parse_primary()

    def parse_primary(self) -> Node:
        tok = self.peek()
        if tok.kind in ("INT", "FLOAT", "TEXT"):
            self.advance()
            return Literal(value=tok.value, start=tok.offset, end=tok.end)
        if tok.kind == "KW" and tok.value in ("TRUE", "FALSE", "NULL"):
            self.advance()
            value = {"TRUE": True, "FALSE": False, "NULL": None}[str(tok.value)]
            return Literal(value=value, start=tok.offset, end=tok.end)
        if tok.kind == "IDENT":
            return self.parse_ident_primary()
        if self.accept_op("("):
            open_tok = tok
            node = self.parse_expr()
            close = self.expect_op(")")
            return dataclasses.replace(
                node, start=open_tok.offset, end=close.end)
        raise ParseError(f"unexpected {tok.text!r}", tok.offset)

    def parse_ident_primary(self) -> Node:
        tok = self.advance()  # the identifier
        name = str(tok.value)
        if self.accept_op("("):
            return self.finish_call(tok, name)
        if self.accept_op("."):
            col = self.expect_ident()
            return ColumnRef(table=name, name=str(col.value),
                             start=tok.offset, end=col.end)
        return ColumnRef(name=name, start=tok.offset, end=tok.end)

    def finish_call(self, tok: Token, name: str) -> Node:
        """Parse the argument list of a call after '('."""
        args: list[Node] = []
        star = False
        if self.accept_op(")"):
            end = self.tokens[self.pos - 1].end
        else:
            if self.accept_op("*"):
                star = True
            else:
                args.append(self.parse_expr())
                while self.accept_op(","):
                    args.append(self.parse_expr())
            end = self.expect_op(")").end
        lower = name.lower()
        if star and lower != "count":
            raise ParseError(f"only count(*) may use '*'", tok.offset)
        if lower in AGGREGATE_NAMES and any(
            contains_aggregate(a) for a in args
        ):
            raise ParseError("aggregate functions may not nest", tok.offset)
        return FuncCall(name=name, args=tuple(args), star=star,
                        start=tok.offset, end=end)

"""Aggregate functions: count, sum, avg, min, max.

Aggregates ignore NULL inputs entirely, except ``count(*)`` which counts rows.
Over a group with no non-NULL input, ``count`` is 0 and ``sum``/``avg``/``min``/
``max`` are all NULL.
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from .errors import ArityError
from .value import INT, arith, compare_lt, is_numeric, type_of
from .errors import TypeMismatchError

if TYPE_CHECKING:
    from .expr import Row
    from .parser import FuncCall, Node

AGGREGATE_NAMES = frozenset({"count", "sum", "avg", "min", "max"})


def is_aggregate_name(name: str) -> bool:
    """True when ``name`` (any case) is an aggregate function name."""
    return name.lower() in AGGREGATE_NAMES


def find_aggregates(node: Node) -> list[FuncCall]:
    """Collect all aggregate call nodes in an expression tree."""
    from . import parser as _p

    found: list[FuncCall] = []

    def walk(n: Node) -> None:
        if isinstance(n, _p.FuncCall):
            if is_aggregate_name(n.name):
                found.append(n)
                return  # aggregates may not nest; args hold no aggregates
            for a in n.args:
                walk(a)
        elif isinstance(n, (_p.UnaryOp, _p.NotOp, _p.IsNull)):
            walk(n.operand)
        elif isinstance(n, _p.BinaryOp):
            walk(n.left)
            walk(n.right)

    walk(node)
    return found


def contains_aggregate(node: Node) -> bool:
    """True when the expression tree contains an aggregate call."""
    return bool(find_aggregates(node))


def compute(call: FuncCall, rows: list[Row]) -> object:
    """Evaluate one aggregate call over a group's rows."""
    from .expr import eval_expr

    name = call.name.lower()
    if call.star:
        return len(rows)  # count(*): counts rows, NULLs included
    if len(call.args) != 1:
        raise ArityError(f"{call.name} expects 1 argument, got {len(call.args)}")
    values: list[object] = []
    for row in rows:
        v = eval_expr(call.args[0], row)
        if v is not None:
            values.append(v)
    if name == "count":
        return len(values)
    if not values:
        return None  # sum/avg/min/max of no non-NULL input are NULL
    if name == "sum":
        return _sum(values)
    if name == "avg":
        total = _sum(values)
        return float(total) / len(values)  # avg always yields FLOAT
    best = values[0]
    for v in values[1:]:
        if name == "min" and compare_lt(v, best):
            best = v
        elif name == "max" and compare_lt(best, v):
            best = v
    return best


def _sum(values: list[object]) -> object:
    """Sum numeric values; INT when every value is INT, otherwise FLOAT."""
    total: object = 0
    all_int = True
    for v in values:
        if not is_numeric(v):
            raise TypeMismatchError(
                f"sum/avg require numeric input, got {type_of(v)}")
        if type_of(v) != INT:
            all_int = False
        total = arith("+", total, v)
    return total if all_int else float(total)  # type: ignore[arg-type]

"""Expression evaluation.

A :class:`Row` is the evaluation context: cell values plus a scope describing
which (table, column) each position belongs to.  ``agg_values`` holds
precomputed aggregate results keyed by node identity (``id`` of the FuncCall
node); ``aliases`` maps SELECT alias names to this row's output values and is
only populated while evaluating ORDER BY (where an alias wins over an input
column of the same name).
"""

from __future__ import annotations

import dataclasses

from .aggregate import is_aggregate_name
from .errors import (
    AggregateError,
    AmbiguousColumnError,
    ArityError,
    TypeMismatchError,
    UnknownColumnError,
    UnknownFunctionError,
    UnknownTableError,
)
from .parser import BinaryOp, ColumnRef, FuncCall, IsNull, Literal, Node, NotOp, UnaryOp
from .value import (
    TEXT,
    and_,
    arith,
    compare_eq,
    compare_lt,
    is_numeric,
    negate,
    not_,
    type_of,
)


@dataclasses.dataclass(frozen=True)
class Scope:
    """Column provenance for a row: (table name, column name) per position."""

    entries: tuple[tuple[str | None, str], ...]


@dataclasses.dataclass(frozen=True)
class Row:
    values: tuple[object, ...]
    scope: Scope
    agg_values: dict[int, object] | None = None
    aliases: dict[str, object] | None = None


def eval_expr(node: Node, row: Row) -> object:
    """Evaluate an expression node against a row."""
    if isinstance(node, Literal):
        return node.value
    if isinstance(node, ColumnRef):
        return resolve_column(node, row)
    if isinstance(node, UnaryOp):
        return negate(eval_expr(node.operand, row))
    if isinstance(node, BinaryOp):
        return _eval_binary(node, row)
    if isinstance(node, NotOp):
        return not_(_as_logic(eval_expr(node.operand, row)))
    if isinstance(node, IsNull):
        is_null = eval_expr(node.operand, row) is None
        return (not is_null) if node.negated else is_null
    if isinstance(node, FuncCall):
        return _eval_call(node, row)
    raise TypeMismatchError(f"cannot evaluate {node!r}")


def resolve_column(ref: ColumnRef, row: Row) -> object:
    """Resolve a column reference against aliases (ORDER BY) then the scope."""
    if ref.table is None and row.aliases is not None and ref.name in row.aliases:
        return row.aliases[ref.name]
    entries = row.scope.entries
    if ref.table is not None:
        if ref.table not in {t for t, _ in entries}:
            raise UnknownTableError(f"unknown table {ref.table!r}")
        for i, (t, c) in enumerate(entries):
            if t == ref.table and c == ref.name:
                return row.values[i]
        raise UnknownColumnError(f"unknown column {ref.table}.{ref.name}")
    matches = [i for i, (_, c) in enumerate(entries) if c == ref.name]
    if not matches:
        raise UnknownColumnError(f"unknown column {ref.name!r}")
    if len(matches) > 1:
        raise AmbiguousColumnError(f"ambiguous column {ref.name!r}")
    return row.values[matches[0]]


def _as_logic(v: object) -> bool | None:
    """Coerce a value to a logical one; non-booleans raise TypeMismatchError."""
    if v is None or isinstance(v, bool):
        return v
    raise TypeMismatchError(f"expected a logical value, got {type_of(v)}")


def _eval_binary(node: BinaryOp, row: Row) -> object:
    op = node.op
    if op == "AND":
        return and_(
            _as_logic(eval_expr(node.left, row)),
            _as_logic(eval_expr(node.right, row)),
        )
    if op == "OR":
        return or_(
            _as_logic(eval_expr(node.left, row)),
            _as_logic(eval_expr(node.right, row)),
        )
    a = eval_expr(node.left, row)
    b = eval_expr(node.right, row)
    if op in ("+", "-", "*", "/", "%"):
        return arith(op, a, b)
    return _compare(op, a, b)


def _compare(op: str, a: object, b: object) -> bool | None:
    if op == "=":
        return compare_eq(a, b)
    if op == "<>":
        r = compare_eq(a, b)
        return None if r is None else not r
    if op == "<":
        return compare_lt(a, b)
    if op == ">":
        return compare_lt(b, a)
    if op == "<=":
        r = compare_lt(b, a)
        return None if r is None else not r
    # op == ">="
    r = compare_lt(a, b)
    return None if r is None else not r


def _eval_call(node: FuncCall, row: Row) -> object:
    if is_aggregate_name(node.name):
        if row.agg_values is not None and id(node) in row.agg_values:
            return row.agg_values[id(node)]
        raise AggregateError(
            f"aggregate {node.name} is not allowed in this context")
    args = [eval_expr(a, row) for a in node.args]
    return call_scalar(node.name, args)


# ---------------------------------------------------------------------------
# Scalar functions
# ---------------------------------------------------------------------------

def call_scalar(name: str, args: list[object]) -> object:
    """Call a scalar function by (case-insensitive) name."""
    lower = name.lower()
    if lower == "concat":
        _arity(name, args, at_least=2)
        return _concat(args)
    if lower == "upper":
        _arity(name, args, exactly=1)
        return None if args[0] is None else _text(name, args[0]).upper()
    if lower == "lower":
        _arity(name, args, exactly=1)
        return None if args[0] is None else _text(name, args[0]).lower()
    if lower == "length":
        _arity(name, args, exactly=1)
        return None if args[0] is None else len(_text(name, args[0]))
    if lower == "abs":
        _arity(name, args, exactly=1)
        return _abs(name, args[0])
    if lower == "coalesce":
        _arity(name, args, at_least=1)
        for a in args:
            if a is not None:
                return a
        return None
    raise UnknownFunctionError(f"unknown function {name!r}")


def _arity(name: str, args: list[object],
           exactly: int | None = None, at_least: int | None = None) -> None:
    n = len(args)
    if exactly is not None and n != exactly:
        raise ArityError(f"{name} expects {exactly} argument(s), got {n}")
    if at_least is not None and n < at_least:
        raise ArityError(
            f"{name} expects at least {at_least} arguments, got {n}")


def _text(fname: str, v: object) -> str:
    if not isinstance(v, str):
        raise TypeMismatchError(f"{fname} expects TEXT, got {type_of(v)}")
    return v


def _concat(args: list[object]) -> object:
    parts: list[str] = []
    for a in args:
        if a is None:
            return None  # concat is NULL if any argument is NULL
        if not isinstance(a, str):
            raise TypeMismatchError(f"concat expects TEXT, got {type_of(a)}")
        parts.append(a)
    return "".join(parts)


def _abs(fname: str, v: object) -> object:
    if v is None:
        return None
    if not is_numeric(v):
        raise TypeMismatchError(f"{fname} expects a number, got {type_of(v)}")
    return abs(v)  # type: ignore[arg-type]  # preserves INT vs FLOAT

"""Planner: turns a Query into an inspectable Plan of named stages."""

from __future__ import annotations

import dataclasses
from collections.abc import Iterator, Sequence

from .aggregate import find_aggregates
from .parser import FuncCall, Query


@dataclasses.dataclass(frozen=True)
class Stage:
    """One execution stage; ``detail`` carries the associated AST payload."""

    name: str
    detail: object = None


class Plan(Sequence[Stage]):
    """An ordered, inspectable sequence of execution stages."""

    def __init__(self, query: Query, stages: list[Stage]) -> None:
        self.query = query
        self._stages = tuple(stages)

    def __len__(self) -> int:
        return len(self._stages)

    def __getitem__(self, index: int | slice) -> Stage | tuple[Stage, ...]:
        return self._stages[index]

    def __iter__(self) -> Iterator[Stage]:
        return iter(self._stages)

    @property
    def stages(self) -> tuple[Stage, ...]:
        return self._stages

    def stage_names(self) -> list[str]:
        """The stage names in execution order."""
        return [s.name for s in self._stages]


def query_aggregates(query: Query) -> list[FuncCall]:
    """All aggregate calls in SELECT, HAVING and ORDER BY."""
    aggs: list[FuncCall] = []
    for item in query.select:
        aggs.extend(find_aggregates(item.expr))
    if query.having is not None:
        aggs.extend(find_aggregates(query.having))
    for item in query.order_by:
        aggs.extend(find_aggregates(item.expr))
    return aggs


def plan(query: Query) -> Plan:
    """Build the stage pipeline for a query, in execution order."""
    stages = [Stage("FROM", (query.from_table, query.join))]
    if query.where is not None:
        stages.append(Stage("WHERE", query.where))
    if query.group_by:
        stages.append(Stage("GROUP BY", query.group_by))
    if query.group_by or query_aggregates(query):
        stages.append(Stage("AGGREGATE"))
    if query.having is not None:
        stages.append(Stage("HAVING", query.having))
    stages.append(Stage("SELECT", query.select))
    if query.distinct:
        stages.append(Stage("DISTINCT"))
    if query.order_by:
        stages.append(Stage("ORDER BY", query.order_by))
    if query.offset is not None:
        stages.append(Stage("OFFSET", query.offset))
    if query.limit is not None:
        stages.append(Stage("LIMIT", query.limit))
    return Plan(query, stages)

"""Executor: runs a Plan against a set of tables, stage by stage.

Pipeline: FROM/JOIN -> WHERE -> GROUP BY -> AGGREGATE -> HAVING -> SELECT ->
DISTINCT -> ORDER BY -> OFFSET -> LIMIT.
"""

from __future__ import annotations

import dataclasses
import functools

from .aggregate import compute, find_aggregates, is_aggregate_name
from .errors import (
    AggregateError,
    GroupingError,
    UnknownTableError,
)
from .expr import Row, Scope, eval_expr, require_logic
from .parser import ColumnRef, FuncCall, Node, Query, SelectItem, Star
from .planner import Plan, Stage, query_aggregates
from .schema import Table
from .value import compare_lt


@dataclasses.dataclass(frozen=True)
class Result:
    columns: list[str]
    rows: list[list[object]]


@dataclasses.dataclass
class _Ctx:
    query: Query
    tables: dict[str, Table]
    scope: Scope = Scope(())
    rows: list[Row] = dataclasses.field(default_factory=list)
    groups: list[list[Row]] = dataclasses.field(default_factory=list)
    out: list[tuple[Row, tuple[object, ...]]] = dataclasses.field(
        default_factory=list)
    columns: list[str] = dataclasses.field(default_factory=list)
    items: list[SelectItem] = dataclasses.field(default_factory=list)
    alias_pos: dict[str, int] = dataclasses.field(default_factory=dict)
    distinct_done: bool = False


def execute_plan(plan: Plan, tables: dict[str, Table]) -> Result:
    """Execute every stage of a plan in order and return the Result."""
    ctx = _Ctx(query=plan.query, tables=tables)
    for stage in plan:
        _HANDLERS[stage.name](ctx, stage)
    return Result(columns=ctx.columns,
                  rows=[list(values) for _, values in ctx.out])


# ---------------------------------------------------------------------------
# Key normalization: NULL is equal to NULL, INT/FLOAT compare numerically,
# and BOOL never collides with INT (Python's True == 1 must not group/sort
# together).
# ---------------------------------------------------------------------------

def _key_of(v: object) -> tuple[str, object]:
    if v is None:
        return ("null", None)
    if isinstance(v, bool):
        return ("bool", v)
    if isinstance(v, (int, float)):
        return ("num", v)
    return ("text", v)


# ---------------------------------------------------------------------------
# Stage handlers
# ---------------------------------------------------------------------------

def _table(ctx: _Ctx, name: str) -> Table:
    try:
        return ctx.tables[name]
    except KeyError:
        raise UnknownTableError(f"unknown table {name!r}")


def _from(ctx: _Ctx, stage: Stage) -> None:
    table = _table(ctx, ctx.query.from_table)
    entries = tuple((table.name, c.name) for c in table.columns)
    ctx.scope = Scope(entries)
    ctx.rows = [Row(values=tuple(r), scope=ctx.scope) for r in table.rows]
    if ctx.query.join is not None:
        _join(ctx, entries)


def _join(ctx: _Ctx, left_entries: tuple[tuple[str | None, str], ...]) -> None:
    join = ctx.query.join
    assert join is not None
    right = _table(ctx, join.table)
    right_entries = tuple((right.name, c.name) for c in right.columns)
    ctx.scope = Scope(left_entries + right_entries)
    nulls = tuple(None for _ in right.columns)
    out: list[Row] = []
    for lrow in ctx.rows:
        matched = False
        for rvals in right.rows:
            row = Row(values=lrow.values + tuple(rvals), scope=ctx.scope)
            if require_logic(eval_expr(join.on, row)) is True:
                matched = True
                out.append(row)
        if not matched and join.kind == "LEFT":
            out.append(Row(values=lrow.values + nulls, scope=ctx.scope))
    ctx.rows = out


def _where(ctx: _Ctx, stage: Stage) -> None:
    where = ctx.query.where
    assert where is not None
    if find_aggregates(where):
        raise AggregateError("WHERE cannot contain an aggregate function")
    ctx.rows = [
        row for row in ctx.rows
        if require_logic(eval_expr(where, row)) is True
    ]


def _group_by(ctx: _Ctx, stage: Stage) -> None:
    groups: dict[tuple[tuple[str, object], ...], list[Row]] = {}
    for row in ctx.rows:
        key = tuple(_key_of(eval_expr(e, row)) for e in ctx.query.group_by)
        groups.setdefault(key, []).append(row)
    ctx.groups = list(groups.values())  # first-appearance order


def _aggregate(ctx: _Ctx, stage: Stage) -> None:
    if not ctx.groups:
        ctx.groups = [list(ctx.rows)]  # whole input is one group, even empty
    _check_grouping(ctx)
    aggs = query_aggregates(ctx.query)
    reps: list[Row] = []
    for group in ctx.groups:
        agg_values = {id(call): compute(call, group) for call in aggs}
        if group:
            rep = group[0]
        else:
            rep = Row(values=tuple(None for _ in ctx.scope.entries),
                      scope=ctx.scope)
        reps.append(dataclasses.replace(rep, agg_values=agg_values))
    ctx.rows = reps


def _having(ctx: _Ctx, stage: Stage) -> None:
    having = ctx.query.having
    assert having is not None
    ctx.rows = [
        row for row in ctx.rows
        if require_logic(eval_expr(having, row)) is True
    ]


def _select(ctx: _Ctx, stage: Stage) -> None:
    items = _expanded_items(ctx)
    ctx.columns = [_output_name(ctx.query, it) for it in items]
    ctx.alias_pos = {it.alias: i for i, it in enumerate(items) if it.alias}
    ctx.out = [
        (row, tuple(eval_expr(it.expr, row) for it in items))
        for row in ctx.rows
    ]


def _distinct(ctx: _Ctx, stage: Stage) -> None:
    seen: set[tuple[tuple[str, object], ...]] = set()
    out: list[tuple[Row, tuple[object, ...]]] = []
    for row, values in ctx.out:
        key = tuple(_key_of(v) for v in values)
        if key not in seen:
            seen.add(key)
            out.append((row, values))
    ctx.out = out
    ctx.distinct_done = True


def _order_by(ctx: _Ctx, stage: Stage) -> None:
    items = ctx.query.order_by
    keyed = [
        (tuple(eval_expr(oi.expr, _order_row(ctx, row, vals)) for oi in items),
         row, vals)
        for row, vals in ctx.out
    ]
    descs = [oi.desc for oi in items]

    def cmp(a: tuple, b: tuple) -> int:
        for ka, kb, desc in zip(a[0], b[0], descs):
            r = _cmp_key(ka, kb)
            if r:
                return -r if desc else r
        return 0

    keyed.sort(key=functools.cmp_to_key(cmp))  # sort is stable
    ctx.out = [(row, vals) for _, row, vals in keyed]


def _offset(ctx: _Ctx, stage: Stage) -> None:
    ctx.out = ctx.out[int(stage.detail):]  # type: ignore[arg-type]


def _limit(ctx: _Ctx, stage: Stage) -> None:
    ctx.out = ctx.out[: int(stage.detail)]  # type: ignore[arg-type]


_HANDLERS = {
    "FROM": _from,
    "WHERE": _where,
    "GROUP BY": _group_by,
    "AGGREGATE": _aggregate,
    "HAVING": _having,
    "SELECT": _select,
    "DISTINCT": _distinct,
    "ORDER BY": _order_by,
    "OFFSET": _offset,
    "LIMIT": _limit,
}


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _cmp_key(a: object, b: object) -> int:
    """Compare two sort-key values; NULL sorts last in both directions."""
    if a is None and b is None:
        return 0
    if a is None:
        return 1
    if b is None:
        return -1
    if compare_lt(a, b):
        return -1
    if compare_lt(b, a):
        return 1
    return 0


def _order_row(ctx: _Ctx, row: Row, values: tuple[object, ...]) -> Row:
    """Build the evaluation context for ORDER BY expressions.

    Aliases are visible (and win over input columns).  With DISTINCT, only
    output columns may be referenced, so the scope is the output column list.
    """
    aliases = {name: values[i] for name, i in ctx.alias_pos.items()}
    if ctx.distinct_done:
        scope = Scope(tuple((None, c) for c in ctx.columns))
        return Row(values=values, scope=scope,
                   agg_values=row.agg_values, aliases=aliases)
    return dataclasses.replace(row, aliases=aliases)


def _expanded_items(ctx: _Ctx) -> list[SelectItem]:
    """Expand '*' and 't.*' select items into plain column references."""
    if ctx.items:
        return ctx.items
    items: list[SelectItem] = []
    for item in ctx.query.select:
        if not isinstance(item.expr, Star):
            items.append(item)
            continue
        star = item.expr
        matched = False
        for tbl, col in ctx.scope.entries:
            if star.table is None or star.table == tbl:
                matched = True
                ref = ColumnRef(name=col, table=tbl,
                                start=star.start, end=star.end)
                items.append(SelectItem(expr=ref, alias=None))
        if not matched and star.table is not None:
            raise UnknownTableError(f"unknown table {star.table!r}")
    ctx.items = items
    return items


def _output_name(query: Query, item: SelectItem) -> str:
    """Alias, else column name for a bare reference, else collapsed source."""
    if item.alias is not None:
        return item.alias
    if isinstance(item.expr, ColumnRef):
        return item.expr.name
    raw = query.source[item.expr.start:item.expr.end]
    return " ".join(raw.split())


def _same_expr(a: Node, b: Node) -> bool:
    """Structural equality, lenient about table qualification of columns."""
    if isinstance(a, ColumnRef) and isinstance(b, ColumnRef):
        return a.name == b.name and (
            a.table == b.table or a.table is None or b.table is None)
    return a == b


def _group_valid(node: Node, gexprs: tuple[Node, ...], aliases: set[str]) -> bool:
    """A SELECT/HAVING/ORDER BY expression is valid in a grouped query when
    every column reference sits inside an aggregate, an alias reference, or a
    subexpression that is one of the grouping expressions."""
    if any(_same_expr(node, g) for g in gexprs):
        return True
    if isinstance(node, FuncCall) and is_aggregate_name(node.name):
        return True
    if isinstance(node, ColumnRef):
        return node.table is None and node.name in aliases
    if isinstance(node, Star):
        return False
    children: tuple[Node, ...] = ()
    if isinstance(node, FuncCall):
        children = node.args
    elif hasattr(node, "operand"):
        children = (node.operand,)  # type: ignore[attr-defined]
    elif hasattr(node, "left"):
        children = (node.left, node.right)  # type: ignore[attr-defined]
    return all(_group_valid(c, gexprs, aliases) for c in children)


def _check_grouping(ctx: _Ctx) -> None:
    gexprs = ctx.query.group_by
    alias_names = {it.alias for it in ctx.query.select if it.alias}
    targets = [it.expr for it in _expanded_items(ctx)]
    if ctx.query.having is not None:
        targets.append(ctx.query.having)
    for t in targets:
        if not _group_valid(t, gexprs, set()):
            raise GroupingError(
                "SELECT/HAVING item must be an aggregate or a grouping "
                "expression")
    for oi in ctx.query.order_by:
        if not _group_valid(oi.expr, gexprs, alias_names):
            raise GroupingError(
                "ORDER BY item must be an aggregate, an alias or a grouping "
                "expression")

