import ast, pathlib

root = pathlib.Path("microdb")
problems = []
for path in sorted(root.glob("*.py")):
    tree = ast.parse(path.read_text(encoding="utf-8"))
    lines = path.read_text(encoding="utf-8").splitlines()
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            body_start = node.body[0].lineno
            body_end = node.end_lineno
            n = body_end - body_start + 1
            if n > 60:
                problems.append(f"{path}:{node.lineno} {node.name} body={n} lines")
            public = not node.name.startswith("_") or node.name.startswith("__")
            if public:
                if node.returns is None:
                    problems.append(f"{path}:{node.lineno} {node.name} missing return annotation")
                for arg in node.args.args + node.args.kwonlyargs:
                    if arg.arg not in ("self", "cls") and arg.annotation is None:
                        problems.append(f"{path}:{node.lineno} {node.name} param {arg.arg} unannotated")
print("\n".join(problems) if problems else "ALL OK")
